```c
#include <math.h>
#include <stdatomic.h>
#include <larchintrin.h>
#include <stddef.h>
#include <time.h>
#include <stdio.h>
#include <stdint.h>
#include <pthread.h>

#ifndef T
#define T 1
#endif
uint64_t ns()
{
    struct timespec ts;
    if (!timespec_get(&ts, TIME_UTC))
    {
        perror("timespec_get");
    }
    return ts.tv_sec * 1000000000 + ts.tv_nsec;
}

int x = 0;
atomic_flag lock;
size_t n = 1000000;
const size_t th = T;
void* acquire_n()
{
    for (size_t i = 0; i < n; i++)
    {
        while (atomic_flag_test_and_set_explicit(&lock, memory_order_acquire))
        { // different instruction here
            for (size_t i = 0; i < 32; i ++) {
                    __ibar(0);
            }
        };
        x ++;
        atomic_flag_clear_explicit(&lock, memory_order_release);
    }
    return NULL;
}


float run_round()
{
    uint64_t t0 = ns();
    pthread_t a[th];
    for (size_t i = 0; i < th; i++) {
        pthread_create(&a[i], NULL, acquire_n, NULL);
    }
    for (size_t i = 0; i < th; i++) {
        pthread_join(a[i], NULL);
    }
    uint64_t t1 = ns();
    float t = (t1 - t0) / (float)(n * th);
    return t;
}

int main(){
    int n = 100;
    float ssq = 0.0;
    float sqs = 0.0;
    for (size_t i = 0; i < n; i++)
    {
        float f = run_round();
        ssq += f * f;
        sqs += f;
        if (i % 10 == 0){
            printf("%d\n", i);
        }
    }
    float avg = sqs / n;
    float sd = sqrtf(ssq / n - avg * avg);
    printf("avg=%f;sd=%f %d\n", avg, sd, th);
}
